  window.LESSONS["u3_l05"] = {"meta":{"grade":5,"subject":"과학","term":2,"unit":3,"unit_title":"열과 우리 생활","n":5,"covers":"5·6차시","title":"액체와 기체에서는 열이 어떻게 이동할까?","goal":"💧 물을 데울 때 잉크의 움직임을 살펴요. / 🕯️ 공기를 데울 때 붙임딱지의 변화를 살펴요. / 🔄 액체와 기체에서 열이 이동하는 방식 대류를 설명해요.","std":"[6과07-03]","duration_min":80,"lesson_format":"탐구 실험(관찰) · 2세대 19장(7요소)","theme":"열 탐험 연구소","source":"2022 개정 과학 5-2 지도서 3단원(자기주도 원문 없음 — 케이티처 정본)","src_key":"u3_l05"},"slides":[{"id":"s01","stage":"도입","block":"cover","data":{"title":"액체와 기체에서는 열이 어떻게 이동할까?\n잉크와 촛불 실험 (2차시)","emoji":"💧"},"suggested_extras":["v_l5_1"]},{"id":"s02","stage":"도입","block":"review","data":{"title":"지난 시간엔 무엇을 했나요?","content":"지난 시간에는 고체 물질을 따라 열이 이동하는 **전도**를 알았어요. 오늘은 물과 공기처럼 흐르는 물질에서 열이 어떻게 이동하는지 알아봐요.","items":[{"q":"긴 구리판 한쪽을 가열하면 어디부터 뜨거워지나요?","a":"가열한 곳에서 가까운 곳부터"},{"q":"ㄷ자 구리판에서 열은 끊어진 틈을 건너뛰나요?","a":"아니요, 구리판을 따라 이동해요"},{"q":"고체 물질을 따라 열이 이동하는 방식은?","a":"전도"}],"from":"u3_l04"},"suggested_extras":["q_l5_1"]},{"id":"s03","stage":"도입","block":"motivate","data":{"scene_title":"찜기 속 만두","desc":"찜기 바닥에만 물이 끓고 있는데 맨 위 칸의 **만두까지 골고루** 잘 익었어요.","question":"찜기 안의 만두는 **어떻게** 골고루 익을 수 있을까요?","img":"assets/photo/science/steamer_dumplings.jpg","tnote":{"ask":["찜기 안에는 무엇이 들어 있을까요?","맨 위 만두까지 무엇이 갔을까요?"],"watch":"「뚜껑을 닫아서」로만 답하는 경우 — 안의 공기·김에 주목","min":4}},"suggested_extras":["q_l5_2","r_l5_1"]},{"id":"s04","stage":"전개","block":"concept","data":{"fig":{"k":"chain","items":[{"emoji":"🥤","name":"받침대","kind":"컵 두 개"},{"emoji":"💧","name":"잉크 넣기","kind":"바닥 가운데"},{"emoji":"♨️","name":"뜨거운 물","kind":"잉크 아래"},{"emoji":"⬆️","name":"잉크 위로","kind":"옆으로 퍼져요"}]},"title":"물에서 잉크의 움직임","content":"잉크 바로 아래에 **뜨거운 물**이 든 컵을 넣으면 잉크가 **위로 올라갔다가** 옆으로 퍼지며 내려와요.","tnote":{"ask":["잉크는 처음에 어느 쪽으로 움직였나요?","위로 간 잉크는 그다음 어떻게 됐나요?"],"watch":"잉크를 너무 많이 넣는 경우 — 조금만","min":8}},"suggested_extras":["e_l5_1"]},{"id":"s05","stage":"전개","block":"concept","data":{"fig":{"k":"chain","items":[{"emoji":"🟧","name":"붙임딱지","kind":"접어 붙이기"},{"emoji":"🫙","name":"아크릴 통","kind":"벽에 안 닿게"},{"emoji":"🕯️","name":"촛불","kind":"한가운데"},{"emoji":"⬆️","name":"위 먼저","kind":"색이 변해요"}]},"title":"공기에서 붙임딱지의 변화","content":"아크릴 통 한가운데에 촛불을 두면 **윗부분** 붙임딱지의 색깔이 **먼저** 변해요. 데워진 공기가 위로 올라가기 때문이에요.","tnote":{"ask":["어느 붙임딱지가 먼저 변했나요?","촛불과 가까운 옆쪽보다 위가 먼저인 까닭은?"],"watch":"통의 구멍을 막는 경우 — 산소가 들어오는 길","min":8}},"suggested_extras":["t_l5_1"]},{"id":"s06","stage":"전개","block":"concept","data":{"fig":{"k":"bins","bins":[{"name":"데워진 물질","emoji":"🔺","tone":"t0","items":[{"emoji":"⬆️","name":"위로 올라가요"},{"emoji":"🌡️","name":"온도가 높아요"}],"hint":"물·공기 모두"},{"name":"차가운 물질","emoji":"🔻","tone":"t1","items":[{"emoji":"⬇️","name":"아래로 내려가요"},{"emoji":"🔄","name":"다시 데워져요"}],"hint":"돌고 돌아요"}]},"title":"대류","content":"액체나 기체를 가열하면 온도가 높아진 물질이 **위로 올라가고** 온도가 낮은 물질이 **아래로 내려가며** 열이 이동해요. 이를 **대류**라고 해요.","tnote":{"ask":["대류에서 움직이는 것은 무엇인가요?","전도와 무엇이 다를까요?"],"watch":"「열이 위로 간다」로만 말하는 경우 — 물질이 직접 움직여요","min":6}},"suggested_extras":["e_l5_2","t_l5_2"]},{"id":"s07","stage":"전개","block":"concept","data":{"fig":{"k":"ask","q":"대류로 열이 이동하는 예일까요?","yes":[{"emoji":"🫖","name":"주전자 물 전체가 끓어요"},{"emoji":"🔥","name":"난로로 방 전체가 따뜻해요"},{"emoji":"❄️","name":"냉방기로 방이 시원해요"}],"no":[{"emoji":"🍳","name":"프라이팬이 달걀을 익혀요"},{"emoji":"🥄","name":"숟가락이 뜨거워져요"}],"ya":"대류예요","na":"아니에요","note":"물질이 **돌며** 열을 옮겨요"},"title":"생활 속 대류","content":"물을 끓일 때 대류로 물이 **순환**하며 물 전체가 뜨거워지고, 방 안 공기도 대류로 순환하며 **방 전체**의 온도가 높아져요.","tnote":{"ask":["난로는 방의 어디에 두면 좋을까요?","냉방기는 왜 높은 곳에 달까요?"],"watch":"프라이팬도 대류라고 하는 경우 — 고체는 전도","min":6}},"suggested_extras":["q_l5_3"]},{"id":"s08","stage":"전개","block":"misconception","data":{"title":"이런 생각, 맞을까요?","label":"자주 하는 생각","wrong":"잉크가 움직이는 모습이 바로 열이 움직이는 모습이다","right":"열은 **눈에 보이지 않아요**. 잉크와 붙임딱지는 물과 공기가 데워져 **어떻게 움직이는지 보여 주는 도우미**예요.","hint":"「잉크를 넣지 않으면 물속에서 열이 이동하지 않을까요?」 하고 물어 주세요 — 잉크가 없어도 대류는 일어난다는 것을 잇게 해요.","tnote":{"ask":["잉크가 없어도 물이 데워질까요?","잉크는 무엇을 보여 주나요?"],"watch":"「잉크 = 열」로 말하는 경우","min":3}},"suggested_extras":["x_l5_1","x_l5_2"]},{"id":"s09","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ①","scenario":{"icon":"💧","body":"사각 통 바닥의 잉크 아래에 뜨거운 물이 든 컵을 넣었어요."},"question":"잉크는 처음에 어느 쪽으로 움직일까요?","options":[{"text":"위쪽으로","correct":true},{"text":"아래쪽으로"},{"text":"움직이지 않는다"},{"text":"통 밖으로"}],"note":"풀이: 데워진 물이 위로 올라가며 잉크도 위로 올라가요. → **위쪽으로**"},"suggested_extras":["t_l5_3"]},{"id":"s10","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ②","scenario":{"icon":"🔄","body":"액체와 기체에서 열의 이동을 정리해요."},"question":"대류를 바르게 말한 것을 모두 고르세요.","options":[{"text":"온도가 높아진 물질이 위로 올라간다","correct":true},{"text":"온도가 낮은 물질이 아래로 내려온다","correct":true},{"text":"액체와 기체에서 열이 이동하는 방식이다","correct":true},{"text":"고체 물질을 따라 열이 이동하는 방식이다"}],"multi":true,"note":"풀이: 고체 물질을 따라 이동하는 것은 전도예요. → 알맞은 것 **3개**"},"suggested_extras":["e_l5_3"]},{"id":"s11","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ③","scenario":{"icon":"🔥","body":"추운 겨울, 방 안을 따뜻하게 하려고 해요."},"question":"방 전체를 빨리 따뜻하게 하려면 난로를 어디에 두는 것이 좋을까요?","options":[{"text":"방의 아래쪽","correct":true},{"text":"천장 가까이"},{"text":"창문 밖"},{"text":"옷장 안"}],"note":"풀이: 아래에서 데워진 공기가 위로 올라가며 대류로 방 전체가 따뜻해져요. → **방의 아래쪽**"},"suggested_extras":["q_l5_4"]},{"id":"s12","stage":"기본문제","block":"leveled_problem","data":{"title":"수준을 골라 풀어요","levels":{"기본":{"q":"액체와 기체에서 열이 이동하는 방식은 무엇인가요?","a":"대류","steps":["잉크와 촛불 실험을 떠올린다","데워진 물질이 위로 간 것을 생각한다","대류라고 답한다"]},"도전":{"q":"냉방기를 방의 높은 곳에 다는 까닭을 대류로 말해 봐요.","a":"차가운 공기는 아래로 내려오고 데워진 공기는 위로 올라가며 순환해 방 전체가 시원해진다","steps":["차가운 공기가 움직이는 쪽을 떠올린다","높은 곳에서 나온 공기가 어디로 갈지 생각한다","순환으로 방 전체가 시원해진다고 쓴다"]},"심화":{"q":"주전자 바닥만 가열해도 물 전체가 끓는 까닭을 물의 움직임을 화살표로 그려 설명해 봐요.","a":"여러 답 (예: 바닥의 물이 데워져 위로 올라가고 위의 차가운 물이 내려와 데워지기를 되풀이한다)","open":true}},"tnote":{"ask":["기본에서 대류를 말했나요?","도전에서 공기의 움직임을 썼나요?"],"watch":"심화에서 화살표가 한 방향으로만 그려진 경우","min":6}},"suggested_extras":["q_l5_5","g_l5_1"]},{"id":"s13","stage":"응용문제","block":"offline_activity","data":{"title":"액체와 기체에서 열이 이동하는 방식 알아보기","type":"group","goal":"사각 통 바닥에 잉크를 넣고 아래에 뜨거운 물이 든 컵을 밀어 넣어 잉크의 움직임을 살피고, 아크릴 통 한가운데에 촛불을 두어 붙임딱지가 변하는 차례를 살핀 뒤 대류를 정리하기","steps":["필름 위에 컵 두 개로 받침대를 만들고 물을 담은 사각 통을 올린다","스포이트로 통 바닥 가운데에 잉크를 조금 넣고 아래에 뜨거운 물 컵을 밀어 넣는다","아크릴 통 안에 열 변색 붙임딱지를 붙이고 한가운데에 촛불을 둔다","잉크와 붙임딱지의 변화를 그림으로 그리고 대류를 정리한다"],"solo":["잉크 실험 사진에 물이 움직이는 화살표를 그린다","방 안 난로와 냉방기의 알맞은 자리를 쓴다"],"materials":["투명한 사각 통","컵 3개","필름 2장","물·뜨거운 물","스포이트","잉크","고온용 열 변색 붙임딱지","구멍 뚫린 아크릴 통","초·점화기","실험복·보안경·안전 장갑","실험관찰 42~43쪽"],"minutes":50,"tnote":{"ask":["잉크가 처음 움직인 쪽을 썼나요?","붙임딱지가 변한 차례를 그렸나요?"],"watch":"뜨거운 물을 맨손으로 옮기거나 잉크가 튀는 경우","min":50}},"suggested_extras":["g_l5_2","t_l5_4"]},{"id":"s14","stage":"응용문제","block":"real_world","data":{"title":"난방기는 아래, 냉방기는 위","scenario":{"icon":"🏠","body":"집에서 **난방기**는 방 아래쪽에, **냉방기**는 높은 곳에 다는 경우가 많아요. 아래에서 데워진 공기는 위로, 위에서 나온 차가운 공기는 아래로 움직이며 **방 전체 공기가 순환**하기 때문이에요."},"content":"기구의 자리를 정할 때 **대류**를 이용해요."},"suggested_extras":["r_l5_2","r_l5_3"]},{"id":"s15","stage":"응용문제","block":"advanced_problem","data":{"title":"생각을 넓혀요","context":"뜨거운 물과 차가운 물을 각각 다른 색 잉크로 물들였어요. 차가운 물 위에 뜨거운 물을 조심히 부으면 어떻게 될까요?","challenge":"두 물이 어떻게 놓일지 예상하고, 반대로 부을 때와 견주어 말해 봐요.","note":"풀이: 뜨거운 물은 **위**, 차가운 물은 **아래**에 머무는 편이에요. 반대로 뜨거운 물 위에 차가운 물을 부으면 차가운 물이 **아래로 내려가고** 뜨거운 물이 **위로 올라가며** 섞여요. 데워진 물은 위로, 차가운 물은 아래로 가려는 성질 때문이에요.","tnote":{"ask":["데워진 물은 어디로 가려 할까요?","반대로 부으면 무엇이 움직이나요?"],"watch":"두 경우가 같다고 하는 경우","min":4}},"suggested_extras":["t_l5_5"]},{"id":"s16","stage":"정리","block":"exit_ticket","data":{"title":"오늘 확인해요","items":[{"q":"물을 데우면 데워진 물은 어느 쪽으로 움직이나요?","a":"위쪽으로"},{"q":"아크릴 통에서 먼저 색이 변한 붙임딱지는?","a":"윗부분의 붙임딱지"},{"q":"액체와 기체에서 열이 이동하는 방식은?","a":"대류"}],"self":["오늘 배운 것을 혼자 설명할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]},"suggested_extras":[]},{"id":"s17","stage":"정리","block":"summary","data":{"title":"오늘 배운 것","points":["액체와 기체를 가열하면 온도가 높아진 물질은 **위로**, 낮은 물질은 **아래로** 움직여요.","이렇게 물질이 직접 움직이며 열이 이동하는 방식을 **대류**라고 해요. 대류로 물과 공기가 순환하며 전체가 데워져요.","찜기 맨 위 만두까지 익힌 것은 위로 올라간 뜨거운 김이었어요."],"arrows":["데워진 물질 — 위로 · 차가운 물질 — 아래로","물과 공기가 돌며 전체가 데워져요","다음: 빛에 의해서도 열이 이동할 수 있을까?"]},"suggested_extras":["r_l5_1"]},{"id":"s18","stage":"정리","block":"self_assessment","data":{"title":"스스로 점검해요","items":["📚 지식·이해 — 대류를 설명할 수 있나요?","🔧 과정·기능 — 잉크와 붙임딱지로 열의 이동을 추리할 수 있나요?","💛 가치·태도 — 실험 안전 수칙을 지켰나요?"],"prompts":["우리 집에서 대류를 이용하는 곳을 하나 찾아 써 봐요."]},"suggested_extras":["e_l5_3"]},{"id":"s19","stage":"정리","block":"next_lesson","data":{"title":"다음 시간엔","preview":"햇빛 아래와 그늘에 둔 검은색 판의 온도를 견줘 봐요.","emoji":"☀️"},"suggested_extras":["c_l5_1"]}],"extras":[{"id":"v_l5_1","type":"video","icon":"🎥","title":"대류 개념 영상","url":"https://www.youtube.com/results?search_query=%EC%B4%88%EB%93%B1+5%ED%95%99%EB%85%84+%EA%B3%BC%ED%95%99+%EC%95%A1%EC%B2%B4%EC%99%80+%EA%B8%B0%EC%B2%B4%EC%97%90%EC%84%9C+%EC%97%B4%EC%9D%98+%EC%9D%B4%EB%8F%99+%EB%8C%80%EB%A5%98","description":"잉크가 위로 올라가는 장면.","source":"유튜브 검색 (교사 사전 확인 권장)","fit_slides":["concept","motivate"]},{"id":"q_l5_1","type":"fun_question","icon":"💡","title":"찜기 만두","content":"맨 위 만두까지 무엇이 갔을까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l5_2","type":"fun_question","icon":"💡","title":"주전자","content":"바닥만 데워도 물 전체가 끓는 까닭은?","fit_slides":["concept","basic_problem"]},{"id":"q_l5_3","type":"fun_question","icon":"💡","title":"잉크 없이","content":"잉크가 없어도 물은 데워질까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l5_4","type":"fun_question","icon":"💡","title":"냉방기 자리","content":"냉방기는 왜 높은 곳에 달까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l5_5","type":"fun_question","icon":"💡","title":"연기","content":"촛불 연기는 왜 위로 갈까요?","fit_slides":["concept","basic_problem"]},{"id":"t_l5_1","type":"tip","icon":"🧩","title":"잉크 조금","content":"잉크는 움직임을 보려고 조금만 넣어요(지도서).","fit_slides":["concept","misconception"]},{"id":"t_l5_2","type":"tip","icon":"🧩","title":"필름 깔기","content":"필름을 깔면 뜨거운 물 컵을 쉽게 밀어 넣어요.","fit_slides":["concept","misconception"]},{"id":"t_l5_3","type":"tip","icon":"🧩","title":"구멍 막지 않기","content":"아크릴 통 구멍은 산소가 드는 길이에요.","fit_slides":["concept","misconception"]},{"id":"t_l5_4","type":"tip","icon":"🧩","title":"두 차시","content":"1차시는 물, 2차시는 공기로 나누어도 좋아요.","fit_slides":["concept","misconception"]},{"id":"t_l5_5","type":"tip","icon":"🧩","title":"다음 예고","content":"다음 시간은 운동장에서 햇빛 실험을 해요.","fit_slides":["concept","misconception"]},{"id":"r_l5_1","type":"real_world","icon":"🌍","title":"난방기 자리","content":"아래에 두면 방 전체가 따뜻해요.","fit_slides":["real_world","summary"]},{"id":"r_l5_2","type":"real_world","icon":"🌍","title":"냉방기 자리","content":"위에 달면 방 전체가 시원해요.","fit_slides":["real_world","summary"]},{"id":"r_l5_3","type":"real_world","icon":"🌍","title":"찜기","content":"김이 올라가며 위 칸까지 익혀요.","fit_slides":["real_world","summary"]},{"id":"g_l5_1","type":"game","icon":"🎮","title":"화살표 그리기","content":"그림에 물과 공기의 흐름을 그려요.","fit_slides":["leveled_problem","offline_activity"]},{"id":"g_l5_2","type":"game","icon":"🎮","title":"어디에 둘까","content":"난로·냉방기 자리 맞히기를 해요.","fit_slides":["leveled_problem","offline_activity"]},{"id":"x_l5_1","type":"misconception","icon":"⚠️","title":"잉크=열","content":"잉크 움직임이 열 그 자체라고 여기는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"x_l5_2","type":"misconception","icon":"⚠️","title":"열만 위로","content":"물질은 그대로이고 열만 올라간다고 여기는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"e_l5_1","type":"example","icon":"📝","title":"잉크 실험","content":"사각 통과 잉크 그림을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l5_2","type":"example","icon":"📝","title":"아크릴 통","content":"붙임딱지 변하는 차례 그림을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l5_3","type":"example","icon":"📝","title":"대류 정의","content":"대류 뜻 칸을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"c_l5_1","type":"checklist","icon":"✅","title":"다음 차시 준비","content":"검은색 판 2장·적외선 온도계·초시계·햇빛 보안경·실험관찰 44~45쪽.","fit_slides":["next_lesson"]}]};
